public static int minQueue(Queue<Integer> q) {
    Queue<Integer> temp = new Queue<Integer>();
    int min = q.head();
    while (!q.isEmpty()) {
        int x = q.remove();
        if (x < min) {
            min = x;
        }
        temp.insert(x);
    }
    // מחזירים את האיברים — התור חוזר להיות כמו בהתחלה
    while (!temp.isEmpty()) {
        q.insert(temp.remove());
    }
    return min;
}

public static int lastValue(Queue<Integer> q) {
    Queue<Integer> temp = new Queue<Integer>();
    int last = 0;
    while (!q.isEmpty()) {
        last = q.remove();
        temp.insert(last);
    }
    // מחזירים את האיברים — התור חוזר להיות כמו בהתחלה
    while (!temp.isEmpty()) {
        q.insert(temp.remove());
    }
    return last;
}

